   { \True  ${137}^{\circ}$ }
     { ${132}^{\circ}$  }
    {  ${147}^{\circ}$ }
}{
\begin{tikzpicture}
    % Định nghĩa tâm của đường tròn
    \coordinate (o) at (0,2);

    % Vẽ đường tròn đầy đủ với tâm O và bán kính 3cm, nét vẽ đậm
