    % Vẽ các đoạn thẳng từ tâm O tới các điểm trên đường tròn
    \coordinate (c) at (-2.85,2.99);  % Điểm C trên đường tròn
    \coordinate (d) at (2.85,2.99);   % Điểm D trên đường tròn

    \draw[line width=1.3pt] (o) -- (d);
    \draw[line width=1.3pt] (o) -- (c);
    \draw[line width=1.3pt] (c) -- (d);

    % Vẽ và ghi nhãn các điểm O, C, D
