    \fill (d) circle (1pt) node[above right] {$D$};
    \end{tikzpicture}
}
\loigiai{
$\text{sđ}\wideparen{CD}=\widehat{COD}=137^{\circ}$ (Số đo của cung nhỏ bằng số đo của góc ở tâm chắn cung đó)
}\end{ex}

